function snakeRows(root: TreeNode | null): number[][] {
  const rows: number[][] = [];
  let level: TreeNode[] = root ? [root] : [];
  while (level.length) {
    const vals = level.map(n => n.val);
    rows.push(rows.length % 2 ? vals.reverse() : vals);
    const next: TreeNode[] = [];
    for (const n of level) {
      if (n.left) next.push(n.left);
      if (n.right) next.push(n.right);
    }
    level = next;
  }
  return rows;
}

