class Solution:
    def snakeRows(self, root: Optional[TreeNode]) -> List[List[int]]:
        rows = []
        level = [root] if root else []
        while level:
            vals = [n.val for n in level]
            rows.append(vals[::-1] if len(rows) % 2 else vals)
            level = [c for n in level for c in (n.left, n.right) if c]
        return rows

