function snakeRows(root: TreeNode | null): number[][] {
  const rows: number[][] = [];
  const queue: TreeNode[] = root ? [root] : [];
  let head = 0;
  while (head < queue.length) {
    const size = queue.length - head, flip = rows.length % 2 === 1;
    const row = new Array<number>(size);
    for (let i = 0; i < size; i++) {
      const n = queue[head++];
      row[flip ? size - 1 - i : i] = n.val;
      if (n.left) queue.push(n.left);
      if (n.right) queue.push(n.right);
    }
    rows.push(row);
  }
  return rows;
}

